components.css:
.rating-picker { display: inline-grid; gap: 5px; }
.rating-stars { display: flex; align-items: center; gap: 2px; }
.rating-star { width: 44px; height: 44px; display: grid; place-items: center; border-radius: 50%; color: #7b6a58; flex: 0 0 44px; }
.rating-star svg { display: block; overflow: visible; transition: transform var(--motion-ui) var(--ease-arrive), fill var(--motion-quick), color var(--motion-quick); }
.rating-star.is-filled { color: #654008; }
.rating-star.is-filled svg { fill: var(--saffron,#ffb547); }
.rating-stars[role="radiogroup"] .rating-star:not(:disabled):hover { background: #f6e7cf; }
.rating-stars[role="radiogroup"] .rating-star:not(:disabled):hover svg { transform: translateY(-2px) rotate(-5deg) scale(1.08); }
.rating-stars[role="radiogroup"] .rating-star:active:not(:disabled) svg { transform: scale(.92); }
.rating-star:disabled { cursor: wait; }
.rating-caption { color: var(--muted,#6c5e53); font-size: 13px; padding-left: 8px; min-height: 21px; font-variant-numeric: tabular-nums; }
